package com.hostel;
import com.hostel.dto.Requests.*;
import com.hostel.security.Access;
import com.hostel.service.*;
import com.hostel.controller.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.test.context.ActiveProfiles;
import org.springframework.transaction.annotation.*;
import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;
import org.springframework.security.core.authority.SimpleGrantedAuthority;
import org.springframework.security.core.context.SecurityContextHolder;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.*;
import java.util.concurrent.*;
import static org.junit.jupiter.api.Assertions.*;
import static com.hostel.service.Database.*;
@SpringBootTest @ActiveProfiles("test") @Transactional
class BusinessWorkflowTests {
 @Autowired Database db;@Autowired ContractService contracts;@Autowired MeterService meters;@Autowired InvoiceService invoices;@Autowired Access access;@Autowired CatalogController catalog;@Autowired ContractController contractApi;@Autowired ReportController reports;@Autowired MeterController meterApi;
 long admin,tenantUser,tenant,property,room,contract;
 static BigDecimal b(String x){return new BigDecimal(x);}
 void login(long user,String role){SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(Long.toString(user),null,List.of(new SimpleGrantedAuthority("ROLE_"+role))));}
 @BeforeEach void seed(){String key=UUID.randomUUID().toString();admin=db.insert("users","username,password_hash,role","a"+key,"unused","ADMIN");tenantUser=db.insert("users","username,password_hash,role","t"+key,"unused","TENANT");login(admin,"ADMIN");property=db.insert("properties","property_code,name,address",key.substring(0,20),"Demo","HCM");room=db.insert("rooms","property_id,floor_number,room_code,base_price,max_occupants",property,2,"203",b("3000000"),2);tenant=db.insert("tenant_profiles","user_id,full_name,identity_number",tenantUser,"Khách thuê",key.substring(0,20));contract=id((Map<String,Object>)contracts.create(new Contract(key,room,tenant,LocalDate.of(2026,1,1),LocalDate.of(2027,1,1),b("3000000"),b("3000000"),5)),"id");for(var s:db.rows("select * from service_items where is_mandatory"))db.insert("service_price_configs","property_id,service_item_id,unit_price,effective_from",property,s.get("id"),b(s.get("service_code").equals("WATER")?"20000":s.get("service_code").equals("ELEC")?"3500":"30000"),LocalDate.of(2026,1,1));}
 @AfterEach void clear(){SecurityContextHolder.clearContext();}
 void readings(){meters.record(new Reading(contract,"2026-01","ELECTRICITY",b("200"),LocalDate.of(2026,1,31),b("100")));meters.record(new Reading(contract,"2026-01","WATER",b("128"),LocalDate.of(2026,1,31),b("120")));}
 long draft(){readings();return id(invoices.create(new Invoice(contract,"2026-01",null,null)),"id");}
 long profile(){return db.insert("tenant_profiles","full_name","Thành viên");}
 void amount(String expected,Map<String,Object> row,String key){assertEquals(0,b(expected).compareTo(money(row,key)),key);}
 @Test void schemaHasExactlyApprovedTablesAndEntities(){assertEquals(17,db.jdbc.queryForObject("select count(*)::int from pg_tables where schemaname='public' and tablename<>'flyway_schema_history'",Integer.class));assertEquals(138,db.jdbc.queryForObject("select count(*)::int from information_schema.columns where table_schema='public' and table_name in (select tablename from pg_tables where schemaname='public' and tablename<>'flyway_schema_history')",Integer.class));}
 @Test void invoiceFormulaAndPartialPayment(){long id=draft();amount("3540000",invoices.issue(id),"total_amount");var paid=invoices.pay(id,new Payment("PAY-"+UUID.randomUUID(),b("2000000"),"CASH","Demo"));assertEquals("PARTIALLY_PAID",paid.get("payment_status"));amount("1540000",paid,"balance_due");}
 @Test void sqlDatesAreCalendarDates(){assertEquals(LocalDate.of(2026,2,1),invoices.detail(draft()).get("issue_date"));}
 @Test void overpaymentRejectedWithoutChangingBalance(){long id=draft();invoices.issue(id);assertThrows(Exception.class,()->invoices.pay(id,new Payment("OVER",b("4000000"),"CASH",null)));amount("3540000",invoices.detail(id),"balance_due");}
 @Test void nonPositivePaymentRejected(){long id=draft();invoices.issue(id);assertThrows(Exception.class,()->invoices.pay(id,new Payment("ZERO",BigDecimal.ZERO,"CASH",null)));}
 @Test void duplicateInvoiceRejected(){draft();assertThrows(Exception.class,()->invoices.create(new Invoice(contract,"2026-01",null,null)));}
 @Test void draftCannotBePaid(){long id=draft();assertThrows(Exception.class,()->invoices.pay(id,new Payment("DRAFT",b("1"),"CASH",null)));}
 @Test void issuedInvoiceCannotBeDeleted(){long id=draft();invoices.issue(id);assertThrows(Exception.class,()->invoices.removeDraft(id));}
 @Test void draftRemovalAllowsReadingCorrection(){long id=draft();invoices.removeDraft(id);long water=db.jdbc.queryForObject("select id from meter_readings where contract_id=? and service_item_id=?",Long.class,contract,meters.service("WATER"));amount("9",meters.edit(water,b("129"),"Correction"),"consumption");}
 @Test void billedReadingCannotBeChanged(){long id=draft();long water=db.jdbc.queryForObject("select id from meter_readings where contract_id=? and service_item_id=?",Long.class,contract,meters.service("WATER"));assertThrows(Exception.class,()->meters.edit(water,b("129"),"No"));}
 @Test void firstReadingRequiresOpeningIndex(){assertThrows(Exception.class,()->meters.record(new Reading(contract,"2026-01","WATER",b("128"),LocalDate.of(2026,1,31),null)));}
 @Test void readingCannotGoBackwards(){assertThrows(Exception.class,()->meters.record(new Reading(contract,"2026-01","WATER",b("119"),LocalDate.of(2026,1,31),b("120"))));}
 @Test void subsequentReadingUsesPreviousIndex(){readings();var r=meters.record(new Reading(contract,"2026-02","WATER",b("130"),LocalDate.of(2026,2,28),null));amount("128",r,"old_index");amount("2",r,"consumption");}
 @Test void suppliedOpeningMustMatchPrevious(){readings();assertThrows(Exception.class,()->meters.record(new Reading(contract,"2026-02","WATER",b("130"),LocalDate.of(2026,2,28),b("127"))));}
 @Test void cannotInsertReadingBeforeLaterPeriod(){meters.record(new Reading(contract,"2026-02","WATER",b("130"),LocalDate.of(2026,2,28),b("120")));assertThrows(Exception.class,()->meters.record(new Reading(contract,"2026-01","WATER",b("128"),LocalDate.of(2026,1,31),b("120"))));}
 @Test void duplicateReadingRejected(){readings();assertThrows(Exception.class,()->meters.record(new Reading(contract,"2026-01","WATER",b("129"),LocalDate.of(2026,1,31),b("120"))));}
 @Test void readingDateMustBeInItsPeriod(){assertThrows(Exception.class,()->meters.record(new Reading(contract,"2026-01","WATER",b("128"),LocalDate.of(2026,2,28),b("120"))));}
 @Test void meterCutoffEnforced(){assertThrows(Exception.class,()->meters.record(new Reading(contract,"2026-01","WATER",b("128"),LocalDate.of(2026,1,15),b("120"))));}
 @Test void snapshotPriceSurvivesLaterConfigChange(){long id=draft();invoices.issue(id);db.jdbc.update("update service_price_configs set unit_price=unit_price*2 where property_id=?",property);amount("3540000",invoices.detail(id),"total_amount");}
 @Test void pendingConsumptionAlertBlocksIssue(){long id=draft();long reading=db.jdbc.queryForObject("select min(id) from meter_readings where contract_id=?",Long.class,contract);db.insert("consumption_alerts","meter_reading_id,baseline_average,applied_threshold_percentage,history_months",reading,b("10"),b("50"),3);assertThrows(Exception.class,()->invoices.issue(id));}
 @Test void reviewedAlertAllowsIssue(){long id=draft();long reading=db.jdbc.queryForObject("select min(id) from meter_readings where contract_id=?",Long.class,contract);long alert=db.insert("consumption_alerts","meter_reading_id,baseline_average,applied_threshold_percentage,history_months",reading,b("10"),b("50"),3);meterApi.confirm(alert,new Alert("CONFIRMED","Checked"));assertEquals("ISSUED",invoices.issue(id).get("status"));}
 @Test void incompleteHistoryDoesNotCreatePercentageAlert(){readings();assertEquals(0,db.jdbc.queryForObject("select count(*)::int from consumption_alerts a join meter_readings m on m.id=a.meter_reading_id where m.contract_id=?",Integer.class,contract));}
 @Test void fullHistoryCreatesSnapshotAlert(){db.jdbc.update("update contracts set start_date='2025-10-01' where id=?",contract);for(int n=0;n<3;n++)meters.record(new Reading(contract,"2025-"+(10+n),"ELECTRICITY",b("110").add(b("10").multiply(BigDecimal.valueOf(n))),LocalDate.of(2025,10+n,1).plusMonths(1).minusDays(1),n==0?b("100"):null));meters.record(new Reading(contract,"2026-01","ELECTRICITY",b("200"),LocalDate.of(2026,1,31),null));var alert=db.one("select a.* from v_consumption_alerts a where contract_id=?",contract);amount("10",alert,"baseline_average");assertEquals(3,((Number)alert.get("history_months")).intValue());}
 @Test void overlappingContractsRejected(){assertThrows(Exception.class,()->contracts.create(new Contract(UUID.randomUUID().toString(),room,tenant,LocalDate.of(2026,2,1),LocalDate.of(2027,2,1),b("3000000"),BigDecimal.ZERO,5)));}
 @Test void adjacentContractAllowed(){var next=(Map<String,Object>)contracts.create(new Contract(UUID.randomUUID().toString(),room,tenant,LocalDate.of(2027,1,1),LocalDate.of(2028,1,1),b("3000000"),BigDecimal.ZERO,5));assertNotNull(next.get("id"));}
 @Test void primaryTenantCannotAlsoBeMember(){assertThrows(Exception.class,()->contracts.member(contract,new Member(tenant,"Self",LocalDate.of(2026,1,1))));}
 @Test void membersReferenceSharedProfiles(){long person=profile();long member=id((Map<String,Object>)contracts.member(contract,new Member(person,"Friend",LocalDate.of(2026,1,1))),"id");assertEquals(person,id(db.one("select * from contract_members where id=?",member),"tenant_id"));}
 @Test void roomCapacityEnforced(){contracts.member(contract,new Member(profile(),null,LocalDate.of(2026,1,1)));long other=profile();assertThrows(Exception.class,()->contracts.member(contract,new Member(other,null,LocalDate.of(2026,1,1))));}
 @Test void perPersonChargesUseActualPersonDays(){long service=db.jdbc.queryForObject("select id from service_items where service_code='PARKING'",Long.class);db.insert("service_price_configs","property_id,service_item_id,unit_price,effective_from",property,service,b("31000"),LocalDate.of(2026,1,1));long member=id((Map<String,Object>)contracts.member(contract,new Member(profile(),null,LocalDate.of(2026,1,1))),"id");contractApi.depart(contract,member,new ContractController.Departure(LocalDate.of(2026,1,16)));long invoice=draft();var line=db.one("select * from v_invoice_lines where invoice_id=? and service_item_id=?",invoice,service);amount("46000",line,"subtotal");assertEquals(46,((Number)line.get("quantity")).intValue());}
 @Test void staffCannotReadUnassignedProperty(){long staff=db.insert("users","username,password_hash,role","s"+UUID.randomUUID(),"x","STAFF");login(staff,"STAFF");assertThrows(Exception.class,()->access.contract(contract));}
 @Test void assignmentAppliesToWholeProperty(){long staff=db.insert("users","username,password_hash,role","s"+UUID.randomUUID(),"x","STAFF");db.insert("employee_assignments","user_id,property_id",staff,property);login(staff,"STAFF");assertEquals(contract,id(access.contract(contract),"id"));}
 @Test void tenantCannotReadDraftOrReceiveMoney(){long invoice=draft();login(tenantUser,"TENANT");assertThrows(Exception.class,()->invoices.detail(invoice));assertThrows(Exception.class,()->invoices.pay(invoice,new Payment("DENIED",b("1"),"CASH",null)));}
 @Test void otherTenantCannotReadContract(){long other=db.insert("users","username,password_hash,role","t"+UUID.randomUUID(),"x","TENANT");login(other,"TENANT");assertThrows(Exception.class,()->access.contract(contract));}
 @Test void checkoutProratesAndOffsetsDepositOnce(){meters.recordSettlement(new Reading(contract,"2026-01","ELECTRICITY",b("120"),LocalDate.of(2026,1,15),b("100")));meters.recordSettlement(new Reading(contract,"2026-01","WATER",b("122"),LocalDate.of(2026,1,15),b("120")));var x=(Map<String,Object>)contracts.checkout(contract,new Checkout(LocalDate.of(2026,1,16),b("120"),b("122"),BigDecimal.ZERO,"End"));amount("1423870.97",x,"settlement_amount");var bill=db.one("select * from v_invoice_balances where contract_id=?",contract);amount("0",bill,"balance_due");amount("0",bill,"cash_received");assertEquals("TERMINATED",db.one("select status from contracts where id=?",contract).get("status"));assertThrows(Exception.class,()->contracts.checkout(contract,new Checkout(LocalDate.of(2026,1,16),b("120"),b("122"),BigDecimal.ZERO,"Again")));}
 @Test void dashboardDistinguishesCashFromBilled(){long id=draft();invoices.issue(id);invoices.pay(id,new Payment(UUID.randomUUID().toString(),b("2000000"),"BANK_TRANSFER_MANUAL",null));assertNotNull(reports.dashboard("2026-01"));assertFalse(((List<?>)reports.quarterly()).isEmpty());}
 @Test @Transactional(propagation=Propagation.NOT_SUPPORTED) void concurrentPaymentsCannotExceedBalance()throws Exception{long id=draft();invoices.issue(id);var start=new CountDownLatch(1);try(var pool=Executors.newFixedThreadPool(2)){Callable<Boolean> operation=()->{login(admin,"ADMIN");start.await();try{invoices.pay(id,new Payment(UUID.randomUUID().toString(),b("2000000"),"CASH",null));return true;}catch(org.springframework.web.server.ResponseStatusException e){return false;}finally{SecurityContextHolder.clearContext();}};var a=pool.submit(operation);var c=pool.submit(operation);start.countDown();assertNotEquals(a.get(15,TimeUnit.SECONDS),c.get(15,TimeUnit.SECONDS));}amount("2000000",invoices.detail(id),"paid_amount");amount("1540000",invoices.detail(id),"balance_due");}
 @Test void tenantsCannotReadInternalRoomNotes(){db.jdbc.update("update rooms set internal_note='Private management note' where id=?",room);login(tenantUser,"TENANT");assertFalse(access.room(room).containsKey("internal_note"));var rooms=(List<Map<String,Object>>)catalog.rooms();assertTrue(rooms.stream().noneMatch(r->r.containsKey("internal_note")));}
 @Test void staffCanReuseAnExistingMemberProfileForAnAdjacentContract(){long person=profile();contracts.member(contract,new Member(person,"Child",LocalDate.of(2026,1,1)));long staff=db.insert("users","username,password_hash,role","s"+UUID.randomUUID(),"x","STAFF");db.insert("employee_assignments","user_id,property_id",staff,property);login(staff,"STAFF");long next=id((Map<String,Object>)contracts.create(new Contract(UUID.randomUUID().toString(),room,tenant,LocalDate.of(2027,1,1),LocalDate.of(2028,1,1),b("3000000"),BigDecimal.ZERO,5)),"id");assertNotNull(((Map<?,?>)contracts.member(next,new Member(person,"Child",LocalDate.of(2027,1,1)))).get("id"));}
}
